/* LIA OS v1 — local-first personal workspace. No API keys, external DB, or hidden tracking. */
const STORAGE_KEY='lia-os-v1';
const CATEGORIES=['Personal','Taikinsa','Encargos USA','Mariè','Dans Lia Vie','Modelaje','Diseño de moda','Universidad','Finanzas','Bienestar','Creatividad'];
const navGroups=[
 {title:'MI ESPACIO',links:[['overview','◈','Overview'],['tasks','☑','Mis tareas'],['calendar','▦','Calendario'],['projects','◇','Proyectos'],['habits','♡','Hábitos'],['focus','◎','Focus mode']]},
 {title:'WORK & BUSINESS',links:[['content','▤','Taikinsa Studio'],['orders','◫','Encargos USA'],['brands','✧','Mis marcas'],['finance','＄','Finanzas']]},
 {title:'CREATIVE LIFE',links:[['creative','✴','Idea Vault'],['model','◉','Modelaje'],['study','▣','Investigación'],['journal','❦','Mi diario']]},
 {title:'SISTEMA',links:[['settings','⚙','Configuración']]}
];
const pageTitles={overview:'Overview',tasks:'Mis tareas',calendar:'Calendario',projects:'Proyectos',habits:'Hábitos',focus:'Focus mode',content:'Taikinsa Studio',orders:'Encargos USA',brands:'Mis marcas',finance:'Finanzas',creative:'Idea Vault',model:'Modelaje',study:'Investigación',journal:'Mi diario',settings:'Configuración'};
const seed=()=>({version:1,settings:{name:'Lia',theme:'light',portfolio:'',focusMinutes:25,shippingRate:5,fx:4000},tasks:[],projects:[],events:[],habits:[],habitLogs:{},transactions:[],goals:[],orders:[],products:[],content:[],ideas:[],castings:[],sources:[],journal:[]});
function getData(){try{const raw=JSON.parse(localStorage.getItem(STORAGE_KEY));if(!raw||typeof raw!=='object')return seed();const s=seed();for(const k of Object.keys(s)){if(Array.isArray(s[k]))s[k]=Array.isArray(raw[k])?raw[k]:[];else if(k==='settings')s.settings={...s.settings,...(raw.settings||{})};else if(k==='habitLogs')s.habitLogs=raw.habitLogs&&typeof raw.habitLogs==='object'?raw.habitLogs:{}}return s}catch{return seed()}}
let db=getData(),current='overview',calendarOffset=0,uiFilters={},timer={mode:25,remaining:25*60,running:false,handle:null};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`;
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(db))}catch{notify('No se pudo guardar: revisa el almacenamiento del navegador.')}}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dayShift(s,n){const d=new Date(`${s}T12:00:00`);d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function niceDate(s){if(!s)return 'Sin fecha';const d=new Date(`${s}T12:00:00`);return Number.isNaN(d.getTime())?esc(s):d.toLocaleDateString('es-CO',{day:'numeric',month:'short',year:'numeric'})}
function money(n){return new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Number(n)||0)}
function num(v){return Number(v)||0}function pct(v){return Math.min(100,Math.max(0,Math.round(num(v))))}
function short(v,n=74){v=String(v??'');return esc(v.length>n?v.slice(0,n-1)+'…':v)}
function opt(v){return esc(v||'')}
function badge(s){const key=String(s||'').toLowerCase();const cls=key.includes('done')||key.includes('hecho')||key.includes('complet')||key.includes('pagado')||key.includes('public')||key.includes('confirmado')?'green':key.includes('pend')||key.includes('idea')?'amber':key.includes('curso')||key.includes('progreso')||key.includes('producción')?'blue':key.includes('cancel')?'red':'wine';return `<span class="chip ${cls}">${esc(s||'Sin estado')}</span>`}
function progressBar(p,extra=''){return `<div class="progress ${extra}"><span style="width:${pct(p)}%"></span></div>`}
function notify(message){const el=$('#toast');el.textContent=message;el.style.display='block';clearTimeout(notify.t);notify.t=setTimeout(()=>el.style.display='none',3500)}
function sectionHead(eyebrow,title,subtitle,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1><p>${subtitle}</p></div><div class="head-actions">${action}</div></div>`}
function addBtn(collection,label='Nuevo'){return `<button class="btn btn-primary" data-new="${collection}">＋ ${label}</button>`}
function empty(title,msg='Crea tu primer registro para empezar.'){return `<div class="empty-state"><div class="empty-icon">✧</div><strong>${esc(title)}</strong><div>${esc(msg)}</div></div>`}
function actionButtons(coll,id){return `<div class="table-actions"><button data-edit="${coll}" data-id="${esc(id)}">Editar</button><button class="danger" data-delete="${coll}" data-id="${esc(id)}">Borrar</button></div>`}
function navTo(page){current=pageTitles[page]?page:'overview';location.hash=current;calendarOffset=0;uiFilters={};closeSidebar();render();window.scrollTo({top:0,behavior:'instant'})}
function buildNav(){let out='';navGroups.forEach(g=>{out+=`<div class="nav-group"><div class="nav-title">${g.title}</div>`;g.links.forEach(([key,sym,label])=>{out+=`<button class="nav-item ${key===current?'active':''}" data-nav="${key}"><span class="nav-icon">${sym}</span>${label}</button>`});out+='</div>'});$('#nav').innerHTML=out;$('#breadcrumbCurrent').textContent=pageTitles[current]||'Overview'}
function render(){buildNav();document.body.classList.toggle('dark',db.settings.theme==='dark');$('#main').innerHTML=({overview:renderOverview,tasks:renderTasks,calendar:renderCalendar,projects:renderProjects,habits:renderHabits,focus:renderFocus,content:renderContent,orders:renderOrders,brands:renderBrands,finance:renderFinance,creative:renderCreative,model:renderModel,study:renderStudy,journal:renderJournal,settings:renderSettings}[current]||renderOverview)()}
function metric(label,value,foot,symbol){return `<div class="panel"><span class="metric-symbol">${symbol}</span><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`}
function renderOverview(){
 const name=esc(db.settings.name||'Lia'),date=today(),next=db.tasks.filter(t=>t.status!=='Hecho').sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,5),done=db.tasks.filter(t=>t.status==='Hecho').length,completed=db.habits.filter(h=>db.habitLogs[h.id]?.includes(date)).length,upcoming=[...db.events.filter(e=>e.date>=date).map(e=>({date:e.date,title:e.title,area:e.area})),...db.content.filter(x=>x.publishDate>=date).map(x=>({date:x.publishDate,title:x.title,area:'Taikinsa'}))].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);
 const monthly=db.transactions.filter(x=>(x.date||'').slice(0,7)===date.slice(0,7)),income=monthly.filter(x=>x.kind==='Ingreso').reduce((a,x)=>a+num(x.amount),0);
 const projectCards=db.projects.slice(0,3).map(p=>`<div class="action-card"><div class="card-top"><strong>${esc(p.name)}</strong>${badge(p.status)}</div><div class="list-row-sub">${esc(p.area||'Personal')} · ${p.deadline?niceDate(p.deadline):'Sin fecha límite'}</div><div class="goal-bar">${progressBar(p.progress||0)}</div></div>`).join('');
 return `<div class="hero"><div class="hero-copy"><div class="eyebrow">WELCOME BACK · ${new Date().toLocaleDateString('es-CO',{weekday:'long',day:'numeric',month:'long'}).toUpperCase()}</div><h2>Tu vida, a tu manera, ${name}.</h2><p>Un día a la vez. Todo lo importante, en un solo lugar.</p><button class="btn" style="margin-top:18px;background:#fff;color:#62213a" data-action="quickadd">＋ Capturar una idea o tarea</button></div><div class="hero-art">L.</div></div>
 <div class="grid cols-4">${metric('Tareas pendientes',db.tasks.filter(x=>x.status!=='Hecho').length,'Lo que queda por hacer','☑')}${metric('Proyectos activos',db.projects.filter(x=>x.status==='En progreso').length,'Construyendo tu futuro','◇')}${metric('Hábitos de hoy',`${completed}/${db.habits.length}`,'Pequeñas victorias','♡')}${metric('Ingresos del mes',money(income),'Registrados en finanzas','↗')}</div>
 <div class="section-title">Tu día en un vistazo</div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Tu siguiente paso</h3><button class="linkish" data-nav="tasks">Todas las tareas →</button></div>${next.length?next.map(t=>`<div class="list-row"><input class="check" type="checkbox" data-task-toggle="${esc(t.id)}" ${t.status==='Hecho'?'checked':''} aria-label="Completar tarea"><div class="list-row-body"><div class="list-row-title">${esc(t.title)}</div><div class="list-row-sub">${esc(t.area)} · ${t.due?niceDate(t.due):'Sin fecha'} ${t.due&&t.due<date?'· VENCIDA':''}</div></div>${badge(t.priority)}</div>`).join(''):empty('Tu lista está despejada','Añade tus primeras tareas para comenzar.')}</div>
 <div class="panel"><div class="panel-head"><h3>Próximamente</h3><button class="linkish" data-nav="calendar">Ver calendario →</button></div>${upcoming.length?upcoming.map(e=>`<div class="list-row"><div class="chip wine">${niceDate(e.date)}</div><div class="list-row-body"><div class="list-row-title">${esc(e.title)}</div><div class="list-row-sub">${esc(e.area||'General')}</div></div></div>`).join(''):empty('Nada pendiente en tu agenda','Añade eventos, grabaciones y reuniones.')}</div></div>
 <div class="section-title">Tus espacios</div><div class="quick-grid">${[['content','▤','Taikinsa Studio','Ideas y publicaciones'],['orders','◫','Encargos USA','Costos y pedidos'],['creative','✴','Idea Vault','Inspírate y crea'],['finance','＄','Money Map','Dinero bajo control']].map(([id,ico,title,sub])=>`<button class="quick-tile" data-nav="${id}"><span>${ico}</span><strong>${title}</strong><small>${sub}</small></button>`).join('')}</div>
 <div class="section-title">Proyectos en movimiento</div><div class="grid cols-2"><div class="panel"><div class="panel-head"><h3>Prioridades actuales</h3><button class="linkish" data-nav="projects">Ver todos →</button></div>${projectCards||empty('Tu siguiente gran proyecto','Crea proyectos para visualizar su avance.')}</div><div class="panel"><div class="panel-head"><h3>Constancia de hoy</h3><button class="linkish" data-nav="habits">Ver hábitos →</button></div>${db.habits.length?db.habits.slice(0,6).map(h=>`<div class="list-row"><button class="habit-toggle ${db.habitLogs[h.id]?.includes(date)?'done':''}" data-habit-toggle="${h.id}" title="Marcar hábito">${db.habitLogs[h.id]?.includes(date)?'✓':'○'}</button><div class="list-row-body"><div class="list-row-title">${esc(h.name)}</div><div class="list-row-sub">${esc(h.area||'Personal')}</div></div></div>`).join(''):empty('Pequeños hábitos, grandes cambios','Comienza creando uno o dos hábitos.')}</div></div>`}
function renderTasks(){const f=uiFilters;const items=db.tasks.filter(x=>(!f.status||x.status===f.status)&&(!f.area||x.area===f.area)&&(!f.query||(x.title+' '+x.notes).toLowerCase().includes(f.query.toLowerCase()))).sort((a,b)=>(a.status==='Hecho')-(b.status==='Hecho')||(a.due||'9999').localeCompare(b.due||'9999'));const done=db.tasks.filter(x=>x.status==='Hecho').length;
 return `${sectionHead('PRODUCTIVITY','Mis tareas','Que tus ideas dejen de ser pendientes eternos.',addBtn('tasks','Nueva tarea'))}<div class="grid cols-3" style="margin-bottom:20px">${metric('Total',db.tasks.length,'Todas las tareas','▤')}${metric('Completadas',done,`${db.tasks.length?pct(done/db.tasks.length*100):0}% del total`,'✓')}${metric('Para hoy',db.tasks.filter(x=>x.due===today()&&x.status!=='Hecho').length,'En tu agenda','▦')}</div><div class="filters"><select class="filter-select" data-filter="status"><option value="">Todos los estados</option>${['Pendiente','En progreso','Hecho'].map(s=>`<option ${f.status===s?'selected':''}>${s}</option>`).join('')}</select><select class="filter-select" data-filter="area"><option value="">Todas las áreas</option>${CATEGORIES.map(s=>`<option ${f.area===s?'selected':''}>${s}</option>`).join('')}</select><input class="filter-input" data-filter="query" placeholder="Buscar tarea (pulsa Enter)" value="${esc(f.query||'')}" /></div><div class="panel">${items.length?items.map(x=>`<div class="list-row"><input class="check" type="checkbox" data-task-toggle="${esc(x.id)}" ${x.status==='Hecho'?'checked':''} aria-label="Cambiar estado"><div class="list-row-body"><div class="list-row-title ${x.status==='Hecho'?'checked-text':''}">${esc(x.title)}</div><div class="list-row-sub">${esc(x.area)} · ${x.due?niceDate(x.due):'Sin fecha'}${x.projectId?' · '+esc(db.projects.find(p=>p.id===x.projectId)?.name||'Proyecto'):''}</div></div>${badge(x.priority)}${badge(x.status)}${actionButtons('tasks',x.id)}</div>`).join(''):empty('No hay tareas con esos filtros','Crea una tarea o cambia los filtros.')}</div>`}
function renderProjects(){return `${sectionHead('GOALS & EXECUTION','Proyectos','De una idea bonita a un resultado concreto.',addBtn('projects','Nuevo proyecto'))}${db.projects.length?`<div class="grid cols-3">${db.projects.map(p=>{const related=db.tasks.filter(t=>t.projectId===p.id),progress=related.length?Math.round(related.filter(t=>t.status==='Hecho').length/related.length*100):pct(p.progress);return `<div class="panel project-card"><div class="card-top"><span class="chip wine">${esc(p.area)}</span>${badge(p.status)}</div><h3>${esc(p.name)}</h3><div class="card-description">${esc(p.notes||'Tu próximo gran proyecto.')}</div><div class="card-top"><span class="small">Progreso</span><strong>${progress}%</strong></div>${progressBar(progress)}<div class="card-footer"><span>Fecha: ${p.deadline?niceDate(p.deadline):'Sin definir'} · ${related.length} tareas</span>${actionButtons('projects',p.id)}</div></div>`}).join('')}</div>`:empty('Todo empieza con un proyecto','Crea tu primer proyecto: portfolio, lanzamiento, campaña o colección.')}`}
function renderCalendar(){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+calendarOffset);const y=d.getFullYear(),m=d.getMonth(),start=new Date(y,m,1),day=(start.getDay()+6)%7,days=new Date(y,m+1,0).getDate();let cells=['L','M','M','J','V','S','D'].map(w=>`<div class="cal-head">${w}</div>`).join('');for(let i=0;i<Math.ceil((day+days)/7)*7;i++){const date=new Date(y,m,i-day+1),ds=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,out=date.getMonth()!==m;const evs=[...db.events.filter(e=>e.date===ds).map(e=>({title:e.title,type:'event'})),...db.tasks.filter(t=>t.due===ds&&t.status!=='Hecho').map(t=>({title:t.title,type:'task'})),...db.content.filter(c=>c.publishDate===ds).map(c=>({title:c.title,type:'event'})),...db.castings.filter(c=>c.date===ds).map(c=>({title:c.brand,type:'event'}))];cells+=`<button class="cal-day ${out?'outside':''} ${ds===today()?'today':''}" data-date="${ds}" title="Nuevo evento el ${ds}"><span class="cal-num">${date.getDate()}</span>${evs.slice(0,3).map(e=>`<span class="cal-dot ${e.type==='task'?'task':''}">${short(e.title,18)}</span>`).join('')}${evs.length>3?`<span class="cal-dot">+ ${evs.length-3} más</span>`:''}</button>`}
 return `${sectionHead('PLAN YOUR DAYS','Calendario','Tu agenda integra eventos, fechas de tareas, castings y publicaciones.',addBtn('events','Nuevo evento'))}<div class="panel"><div class="panel-head"><h3>${d.toLocaleDateString('es-CO',{month:'long',year:'numeric'})}</h3><div class="cal-nav"><button data-cal="-1" title="Mes anterior">‹</button><button data-cal="0">Hoy</button><button data-cal="1" title="Mes siguiente">›</button></div></div><div class="cal-legend"><span><b></b> Eventos y publicaciones</span><span><b class="task-square"></b> Tareas</span></div><div class="monthly-calendar">${cells}</div><div class="hint">Toca una fecha para crear un evento.</div></div><div class="section-title">Eventos registrados</div>${renderSimpleTable('events',db.events,['title','date','area','time'])}`}
function streak(h){let count=0;let date=today();if(!db.habitLogs[h.id]?.includes(date))date=dayShift(date,-1);while(db.habitLogs[h.id]?.includes(date)){count++;date=dayShift(date,-1)}return count}
function renderHabits(){const t=today();const done=db.habits.filter(h=>db.habitLogs[h.id]?.includes(t)).length;return `${sectionHead('DAILY RITUALS','Mis hábitos','La constancia cuenta más que la perfección.',addBtn('habits','Crear hábito'))}<div class="grid cols-3" style="margin-bottom:20px">${metric('Hábitos activos',db.habits.length,'Tu selección personal','♡')}${metric('Completados hoy',done,`${db.habits.length?pct(done/db.habits.length*100):0}% del día`,'✓')}${metric('Mejor racha',Math.max(0,...db.habits.map(streak)),'Días seguidos','♧')}</div><div class="grid cols-2">${db.habits.map(h=>`<div class="panel"><div class="habit-card"><div><div class="list-row-title">${esc(h.name)}</div><div class="list-row-sub">${esc(h.area||'Personal')} · ${streak(h)} días de racha</div></div><button class="habit-toggle ${db.habitLogs[h.id]?.includes(t)?'done':''}" data-habit-toggle="${h.id}" title="${db.habitLogs[h.id]?.includes(t)?'Desmarcar':'Completar'}">${db.habitLogs[h.id]?.includes(t)?'✓':'○'}</button></div><div class="habit-days">${Array.from({length:7},(_,i)=>{const d=dayShift(t,i-6);return `<div class="habit-day ${db.habitLogs[h.id]?.includes(d)?'done':''}" title="${d}">${['D','L','M','M','J','V','S'][new Date(d+'T12:00:00').getDay()]}</div>`}).join('')}</div><div class="card-footer" style="margin-top:14px">${esc(h.notes||'Un paso a la vez')} ${actionButtons('habits',h.id)}</div></div>`).join('')}</div>${!db.habits.length?empty('Construye tu ritual','Ejemplo: entrenar, diario, skincare, leer o dormir temprano.'):''}`}
function orderDetails(o){const price=num(o.priceUSD),ship=num(o.shippingUSD),weight=num(o.weightLb),rate=num(o.shippingRate||db.settings.shippingRate),extra=num(o.extraUSD),fx=num(o.fx||db.settings.fx),margin=num(o.marginPercent),totalUSD=price+ship+weight*rate+extra,costCOP=totalUSD*fx,sellCOP=Math.ceil((costCOP*(1+margin/100))/100)*100;return {totalUSD,costCOP,sellCOP,profit:sellCOP-costCOP,over200:price+ship>200}}
function renderOrders(){const data=db.orders,totalRevenue=data.reduce((a,o)=>a+orderDetails(o).sellCOP,0),profit=data.reduce((a,o)=>a+orderDetails(o).profit,0);return `${sectionHead('USA → COLOMBIA','Encargos USA','Cotiza, controla pedidos y conoce tus márgenes.',addBtn('orders','Nuevo pedido'))}<div class="module-note">Calculadora editable: producto + envío USA + transporte internacional por libra + costos extra, convertido a COP y con porcentaje de margen sobre costo. La tasa de cambio inicial es solo un ejemplo, NO es una cotización actual: actualízala antes de vender. Verifica impuestos y condiciones aduaneras; la app no sustituye una liquidación real.</div><div class="grid cols-3" style="margin-bottom:21px">${metric('Pedidos registrados',data.length,'En tu historial','◫')}${metric('Venta potencial',money(totalRevenue),'Estimación con valores registrados','↗')}${metric('Ganancia estimada',money(profit),'Antes de otros gastos y tributos','＄')}</div>${data.length?`<div class="table-wrap"><table><thead><tr><th>Cliente / Producto</th><th>Estado</th><th>Peso</th><th>Costo total</th><th>Precio sugerido</th><th>Margen estimado</th><th>Acciones</th></tr></thead><tbody>${data.map(o=>{const d=orderDetails(o);return `<tr><td><strong>${esc(o.client||'Cliente sin nombre')}</strong><div class="list-row-sub">${esc(o.item)} · ${esc(o.store||'Tienda')}</div>${d.over200?'<span class="chip amber">Revisar umbral USD 200</span>':''}</td><td>${badge(o.status)}</td><td>${num(o.weightLb).toFixed(2)} lb</td><td>${money(d.costCOP)}</td><td><strong>${money(d.sellCOP)}</strong></td><td class="money-up">${money(d.profit)}</td><td>${actionButtons('orders',o.id)}</td></tr>`}).join('')}</tbody></table></div>`:empty('Tu primera cotización está a un clic','Registra un cliente, precio en USD, libras, envío y margen.')}`}
function renderContent(){const upcoming=db.content.filter(c=>c.status!=='Publicado');return `${sectionHead('SOCIAL MEDIA · CONTENT','Taikinsa Studio','Organiza las ideas, producción y calendario del restaurante.',addBtn('content','Nueva publicación'))}<div class="grid cols-3" style="margin-bottom:21px">${metric('Piezas de contenido',db.content.length,'Planeadas y publicadas','▤')}${metric('En producción',db.content.filter(x=>x.status==='En producción').length,'Ideas en proceso','◉')}${metric('Publicadas',db.content.filter(x=>x.status==='Publicado').length,'Contenido finalizado','✓')}</div><div class="panel"><div class="panel-head"><h3>Pipeline editorial</h3><span class="chip wine">Taikinsa · Hotel Dann Carlton</span></div>${db.content.length?db.content.sort((a,b)=>(a.publishDate||'9999').localeCompare(b.publishDate||'9999')).map(x=>`<div class="list-row"><div class="list-row-body"><div class="list-row-title">${esc(x.title)}</div><div class="list-row-sub">${esc(x.format)} · ${esc(x.platform)} · ${x.publishDate?niceDate(x.publishDate):'Sin fecha'}${x.notes?' · '+short(x.notes,90):''}</div></div>${badge(x.status)}${actionButtons('content',x.id)}</div>`).join(''):empty('Que no se escape ninguna idea','Guarda reels, campañas, stories y publicaciones.')}</div><div class="module-note" style="margin-top:20px">La programación automática en Instagram y la lectura de métricas reales requerirían conectar servicios externos. Aquí organizas y registras el trabajo manualmente.</div>`}
function renderBrands(){const brands=['Mariè','Dans Lia Vie'];const total=db.products.reduce((a,p)=>a+num(p.stock)*num(p.costCOP),0);return `${sectionHead('JEWELRY · ENTREPRENEURSHIP','Mis marcas','El inventario y los números de tus dos marcas.',addBtn('products','Nuevo producto'))}<div class="grid cols-3" style="margin-bottom:20px">${metric('Referencias',db.products.length,'Productos creados','✧')}${metric('Unidades',db.products.reduce((a,p)=>a+num(p.stock),0),'Inventario total','◇')}${metric('Costo del inventario',money(total),'Valor registrado','＄')}</div><div class="grid cols-2" style="margin-bottom:20px">${brands.map(name=>`<div class="panel"><div class="panel-head"><h3>${name}</h3><span class="chip wine">${db.products.filter(p=>p.brand===name).length} referencias</span></div><div class="stat-line"><span>Unidades disponibles</span><strong>${db.products.filter(p=>p.brand===name).reduce((a,p)=>a+num(p.stock),0)}</strong></div><div class="stat-line"><span>Valor de costo</span><strong>${money(db.products.filter(p=>p.brand===name).reduce((a,p)=>a+num(p.costCOP)*num(p.stock),0))}</strong></div></div>`).join('')}</div>${db.products.length?`<div class="table-wrap"><table><thead><tr><th>Producto</th><th>Marca</th><th>Costo</th><th>Venta</th><th>Ganancia / unidad</th><th>Stock</th><th>Acciones</th></tr></thead><tbody>${db.products.map(p=>`<tr><td><strong>${esc(p.name)}</strong><div class="list-row-sub">${short(p.notes||'',70)}</div></td><td>${esc(p.brand)}</td><td>${money(p.costCOP)}</td><td>${money(p.priceCOP)}</td><td class="money-up">${money(num(p.priceCOP)-num(p.costCOP))}</td><td>${num(p.stock)}</td><td>${actionButtons('products',p.id)}</td></tr>`).join('')}</tbody></table></div>`:empty('Tu inventario empieza aquí','Crea referencias para Mariè o Dans Lia Vie.')}`}
function renderFinance(){const f=uiFilters.month||today().slice(0,7),inMonth=db.transactions.filter(t=>(t.date||'').startsWith(f)),incomes=inMonth.filter(t=>t.kind==='Ingreso').reduce((a,x)=>a+num(x.amount),0),expenses=inMonth.filter(t=>t.kind==='Gasto').reduce((a,x)=>a+num(x.amount),0),balance=incomes-expenses;return `${sectionHead('MONEY MAP','Finanzas','Haz que tus metas tengan números reales.',addBtn('transactions','Nuevo movimiento'))}<div class="filters"><label class="tiny muted" for="moneyMonth">Mes:</label><input id="moneyMonth" class="filter-input" style="width:145px" type="month" data-filter="month" value="${f}" /></div><div class="grid cols-3" style="margin-bottom:22px">${metric('Ingresos',money(incomes),'Movimientos registrados','↗')}${metric('Gastos',money(expenses),'Movimientos registrados','↘')}${metric('Balance',money(balance),'Ingresos menos gastos','◎')}</div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Movimientos</h3><button class="linkish" data-new="transactions">+ Añadir</button></div>${inMonth.length?inMonth.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<div class="list-row"><div class="list-row-body"><div class="list-row-title">${esc(x.description||x.category)}</div><div class="list-row-sub">${niceDate(x.date)} · ${esc(x.category)} · ${esc(x.area||'Personal')}</div></div><strong class="${x.kind==='Ingreso'?'money-up':'money-down'}">${x.kind==='Ingreso'?'+':'−'}${money(x.amount)}</strong>${actionButtons('transactions',x.id)}</div>`).join(''):empty('Tu historial está listo','Añade ingresos y gastos para ver el balance.')}</div><div class="panel"><div class="panel-head"><h3>Metas de ahorro</h3><button class="linkish" data-new="goals">+ Meta</button></div>${db.goals.length?db.goals.map(g=>`<div class="action-card"><div class="card-top"><strong>${esc(g.name)}</strong><span class="small">${pct(num(g.current)/Math.max(1,num(g.target))*100)}%</span></div><div class="list-row-sub">${money(g.current)} de ${money(g.target)}</div><div class="goal-bar">${progressBar(num(g.current)/Math.max(1,num(g.target))*100)}</div><div class="card-footer" style="margin-top:10px"><span>${g.deadline?niceDate(g.deadline):'Sin fecha objetivo'}</span>${actionButtons('goals',g.id)}</div></div>`).join(''):empty('Sueños con presupuesto','Crea una meta de ahorro para ver tu avance.')}</div></div><div class="module-note" style="margin-top:19px">Los movimientos financieros se registran manualmente. No hay conexión a bancos ni sincronización automática entre dispositivos.</div>`}
function renderCreative(){return `${sectionHead('THE CREATIVE MIND','Idea Vault','Un lugar para guardar todo lo que tu imaginación produce.',addBtn('ideas','Capturar idea'))}${db.ideas.length?`<div class="grid cols-3">${db.ideas.map(x=>`<div class="panel project-card"><div class="card-top"><span class="chip wine">${esc(x.area)}</span>${badge(x.status)}</div><div class="panel-kicker">${esc(x.type||'Idea')}</div><h3>${esc(x.title)}</h3><div class="card-description">${esc(x.description||'')}</div><div class="card-footer"><span>${x.link?`<a href="${safeUrl(x.link)}" target="_blank" rel="noopener noreferrer">Ver referencia ↗</a>`:'Idea guardada'}</span>${actionButtons('ideas',x.id)}</div></div>`).join('')}</div>`:empty('Que ninguna idea se pierda','Campañas, looks, negocios, moodboards, fotos o futuros proyectos.')}`}
function renderModel(){return `${sectionHead('CAREER · PORTFOLIO','Modelaje','Organiza castings, sesiones y contactos profesionales.',addBtn('castings','Nuevo casting'))}<div class="grid cols-2" style="margin-bottom:20px"><div class="panel"><div class="panel-head"><h3>Tu book digital</h3><span class="chip wine">Portafolio</span></div><p class="small muted">Guarda aquí la URL de tu portafolio de modelo, publicado en GitHub Pages u otro servicio.</p>${db.settings.portfolio?`<a class="btn btn-primary" href="${safeUrl(db.settings.portfolio)}" target="_blank" rel="noopener noreferrer">Abrir mi book ↗</a>`:'<button class="btn" data-nav="settings">Añadir enlace</button>'}</div><div class="panel"><div class="panel-head"><h3>Tu pipeline</h3></div><div class="stat-line"><span>Postulaciones</span><strong>${db.castings.length}</strong></div><div class="stat-line"><span>Confirmadas</span><strong>${db.castings.filter(c=>c.status==='Confirmado').length}</strong></div><div class="stat-line"><span>Pendientes</span><strong>${db.castings.filter(c=>c.status==='Pendiente').length}</strong></div></div></div>${renderSimpleTable('castings',db.castings,['brand','date','type','status','feeCOP'])}`}
function renderStudy(){return `${sectionHead('FASHION · ACADEMIA','Investigación','Bibliografía, conceptos y hallazgos organizados.',addBtn('sources','Añadir fuente'))}<div class="panel" style="margin-bottom:20px"><span class="eyebrow">PROYECTO DE GRADO</span><h3 style="margin-top:7px">Instagram e identidad estética</h3><p class="small muted">Tu espacio para gestionar fuentes y aprendizajes sobre identidad visual, influencers y homogenización estética, con miras a desarrollar tu fashion film.</p><div class="chips"><span class="chip wine">Enfoque mixto</span><span class="chip">Población 18–25 años</span><span class="chip">Bucaramanga</span><span class="chip">Fashion film</span></div></div><div class="panel"><div class="panel-head"><h3>Biblioteca de fuentes</h3><span class="chip wine">${db.sources.length} fuentes</span></div>${db.sources.length?db.sources.map(s=>`<div class="list-row"><div class="list-row-body"><div class="list-row-title">${esc(s.title)}</div><div class="list-row-sub">${esc(s.author||'Autor no registrado')} · ${esc(s.status)}</div><div class="list-row-sub">${short(s.insight||'',160)} ${s.link?`· <a href="${safeUrl(s.link)}" target="_blank" rel="noopener noreferrer">Abrir fuente ↗</a>`:''}</div></div>${actionButtons('sources',s.id)}</div>`).join(''):empty('Cada fuente suma','Registra artículos, documentos, entrevistas y hallazgos.')}</div>`}
function renderJournal(){return `${sectionHead('SLOW LIVING','Mi diario','Un espacio de reflexión sin ruido.',addBtn('journal','Nueva entrada'))}<div class="module-note">Este diario se guarda localmente en tu navegador y no tiene cifrado propio. No escribas contraseñas ni información especialmente sensible en una versión publicada sin autenticación segura.</div>${db.journal.length?`<div class="grid cols-2">${[...db.journal].sort((a,b)=>b.date.localeCompare(a.date)).map(j=>`<div class="panel journal-card"><div class="card-top"><span class="panel-kicker">${niceDate(j.date)}</span>${badge(j.mood||'Reflexión')}</div><h3 style="margin-top:15px">${esc(j.title||'Un momento para mí')}</h3><p>${esc(j.entry)}</p><div class="card-footer"><span>Mi espacio</span>${actionButtons('journal',j.id)}</div></div>`).join('')}</div>`:empty('Cada día tiene su historia','Escribe lo que quieras recordar, agradecer o dejar ir.')}`}
function renderFocus(){const mins=Math.floor(timer.remaining/60),seconds=timer.remaining%60;return `${sectionHead('DEEP WORK','Focus mode','Una sola cosa a la vez. El resto puede esperar.')}<div class="panel" style="max-width:660px;margin:0 auto;text-align:center"><div class="eyebrow">FOCUS SESSION</div><h3 style="margin:12px 0 18px">Haz espacio para lo importante</h3><div class="focus-modes"><button data-focus-mode="25" class="${timer.mode===25?'selected':''}">25 min · Focus</button><button data-focus-mode="50" class="${timer.mode===50?'selected':''}">50 min · Deep work</button><button data-focus-mode="5" class="${timer.mode===5?'selected':''}">5 min · Pausa</button></div><div class="focus-timer" id="focusCounter">${String(mins).padStart(2,'0')}:${String(seconds).padStart(2,'0')}</div><div class="focus-actions"><button class="btn btn-primary" data-action="focusStart">${timer.running?'Pausar':'Empezar'} sesión</button><button class="btn" data-action="focusReset">Reiniciar</button></div><p class="hint" style="margin-top:25px">El temporizador funciona mientras esta pestaña permanezca abierta. No envía notificaciones cuando la cierras.</p></div>`}
function renderSettings(){return `${sectionHead('CUSTOMIZE YOUR LIFE','Configuración','Tu sistema, a tu estilo.')}<div class="two-col"><div class="panel"><div class="panel-head"><h3>Personalización</h3></div><div class="settings-card"><div><strong>Tu nombre</strong><div class="list-row-sub">Así te saluda LIA OS.</div></div><div class="form-inline"><input id="settingName" value="${esc(db.settings.name)}" maxlength="30" aria-label="Tu nombre"><button class="btn btn-sm" data-action="saveName">Guardar</button></div></div><div class="settings-card"><div><strong>Modo de apariencia</strong><div class="list-row-sub">Claro u oscuro.</div></div><button class="btn btn-sm" data-action="theme">${db.settings.theme==='dark'?'Modo claro ☀':'Modo oscuro ☾'}</button></div><div class="settings-card"><div><strong>Portafolio modelo</strong><div class="list-row-sub">Tu página web profesional.</div></div><button class="btn btn-sm" data-action="portfolio">Editar URL</button></div><div class="settings-card"><div><strong>Tipo de cambio USD → COP</strong><div class="list-row-sub">Predeterminado para nuevos pedidos; actualízalo manualmente.</div></div><div class="form-inline"><input id="settingFX" type="number" min="1" step="1" value="${num(db.settings.fx)}" style="width:95px"><button class="btn btn-sm" data-action="saveFX">Guardar</button></div></div><div class="settings-card"><div><strong>Casillero por libra (USD)</strong><div class="list-row-sub">Predeterminado para nuevos pedidos.</div></div><div class="form-inline"><input id="settingShip" type="number" min="0" step="0.1" value="${num(db.settings.shippingRate)}" style="width:78px"><button class="btn btn-sm" data-action="saveShip">Guardar</button></div></div></div><div class="panel"><div class="panel-head"><h3>Datos y respaldo</h3></div><div class="action-card"><h4>Exportar tus datos</h4><p>Descarga un archivo JSON con tus proyectos, finanzas, hábitos y registros.</p><button class="btn" style="margin-top:12px" data-action="export">↧ Exportar respaldo</button></div><div class="action-card"><h4>Importar un respaldo</h4><p>Restaura un archivo JSON exportado anteriormente. Sustituye los datos actuales.</p><button class="btn" style="margin-top:12px" data-action="import">↥ Importar archivo</button><input type="file" id="importFile" accept="application/json,.json" class="hidden"></div><div class="action-card"><h4>Empezar con plantillas</h4><p>Añade ejemplos de proyectos y hábitos que después podrás editar o borrar.</p><button class="btn" style="margin-top:12px" data-action="templates">＋ Añadir plantillas</button></div><div class="warning" style="margin-top:15px"><strong>Privacidad:</strong> publicar el código en GitHub Pages no publica tus registros privados, pero los datos de esta versión se guardan únicamente en el navegador de cada dispositivo. Borrar datos del sitio, navegar en privado o cambiar de dispositivo puede hacer que no estén disponibles. Exporta respaldos periódicamente. No hay cuenta, sincronización ni cifrado de extremo a extremo.</div><button class="btn btn-danger" style="margin-top:20px" data-action="resetAll">Eliminar todos los datos locales</button></div></div>`}
function renderSimpleTable(collection,items,columns){const titles={title:'Título',date:'Fecha',time:'Hora',area:'Área',brand:'Marca / Agencia',type:'Tipo',status:'Estado',feeCOP:'Pago',};if(!items.length)return `<div class="panel">${empty('Todavía no hay registros','Añade el primer registro desde el botón superior.')}</div>`;return `<div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th>${titles[c]||c}</th>`).join('')}<th>Acciones</th></tr></thead><tbody>${items.map(item=>`<tr>${columns.map(c=>`<td>${c==='status'?badge(item[c]):c==='feeCOP'?money(item[c]):c==='date'?niceDate(item[c]):esc(item[c]||'—')}</td>`).join('')}<td>${actionButtons(collection,item.id)}</td></tr>`).join('')}</tbody></table></div>`}
function safeUrl(s){try{const url=new URL(s);return ['https:','http:'].includes(url.protocol)?esc(url.href):'#'}catch{return '#'}}
