 goals:[{name:'name',label:'Meta de ahorro',required:true,wide:true},{name:'target',label:'Objetivo (COP)',type:'number',required:true},{name:'current',label:'Ahorrado (COP)',type:'number',default:0},{name:'deadline',label:'Fecha deseada',type:'date'}],
