 products:[{name:'name',label:'Producto / referencia',required:true,wide:true},{name:'brand',label:'Marca',type:'select',options:['Mariè','Dans Lia Vie'],default:'Mariè'},{name:'stock',label:'Cantidad disponible',type:'number',default:0},{name:'costCOP',label:'Costo unitario COP',type:'number',default:0},{name:'priceCOP',label:'Venta unitaria COP',type:'number',default:0},{name:'notes',label:'Material / proveedor / descripción',type:'textarea',wide:true}],
